def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Markers are overlaid on the large color fields; restore each from the
    # predominant color in its surrounding neighborhood.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1:
                counts = {}
                for rad in (1, 2, 3):
                    for dr in range(-rad, rad + 1):
                        for dc in range(-rad, rad + 1):
                            rr, cc = r + dr, c + dc
                            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] not in (1, 9):
                                counts[grid[rr][cc]] = counts.get(grid[rr][cc], 0) + 1
                    if counts:
                        out[r][c] = max(counts, key=counts.get)
                        break
    return out
